"""Shared public catalog selection and scoped private template editor."""

MARKUP = r'''<section id="template-hub" aria-labelledby="template-hub-title">
<div class="workspace-studio-heading"><h2 id="template-hub-title"><svg class="lucide" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path d="M14 17h7m-3.5-3.5v7"/></svg> Template Hub</h2><button id="hub-refresh" type="button">Refresh templates</button></div>
<p>Choose from the same published templates as the public Workflow Template Hub and save your own version. Your saved workflows below remain available.</p>
<div class="hub-filters"><label>Search templates<input id="hub-search" type="search" maxlength="120" placeholder="Search name, description or agent"></label><label>Category<select id="hub-category"><option value="">All categories</option></select></label></div><details class="context-help" id="hub-search-help"><summary>Search tips</summary><div class="context-help-body"><p>Search matches template names, descriptions and agent step names within the selected category. The count shows matches out of all published templates.</p></div></details><p id="hub-state" role="status" aria-live="polite">Loading available templates…</p><div id="hub-cards" class="hub-grid"></div><nav class="hub-pages" aria-label="Workspace template pages"><button id="hub-prev" type="button">Previous</button><span id="hub-page" role="status" tabindex="-1"></span><button id="hub-next" type="button">Next</button></nav>
<details id="hub-blueprints"><summary>Build an editable workflow from a starter</summary><p>These starters open in the step editor. They require current approved connections and a separate review. Editing an agent graph does not inherit a template's fallback verification.</p><div id="hub-starters" class="hub-grid"></div></details>
<label for="hub-saved">Your saved template workflows</label><select id="hub-saved"><option value="">No saved template workflows yet</option></select><button id="hub-load" type="button">Open saved template</button>
<div id="hub-editor" hidden><h3 id="hub-title"></h3><p id="hub-description"></p><p id="hub-support" class="hub-badge"></p><div id="hub-agents"></div>
<p id="hub-fallback-note">Fallback uses one verified alternative source when an eligible failure occurs. Uncertain requests are never repeated automatically. Availability and verification can expire; review original sources.</p>
<label for="hub-name">Your workflow name</label><input id="hub-name" maxlength="120"><div id="hub-inputs"></div>
<p id="hub-input-note">Use public English search keywords only. Do not include personal or confidential information. The template's reviewed agent graph stays fixed while you change these inputs.</p>
<button id="hub-review" type="button">Review template settings</button><div id="hub-review-box" hidden><h4>Review before saving</h4><dl id="hub-review-fields"></dl><p id="hub-charge"></p><label><input id="hub-save-consent" type="checkbox"> Save these reviewed settings as my workflow.</label><button id="hub-save" type="button">Save template workflow</button></div>
<div id="hub-test" hidden><h4>Test your saved version</h4><label><input id="hub-run-consent" type="checkbox"> <span id="hub-run-notice">Send these public inputs to the listed agents and allow one verified alternative source if needed.</span></label><button id="hub-run" type="button">Run saved template</button><button id="hub-history" type="button">Check test history</button><div id="hub-results" role="status" aria-live="polite"></div><button id="hub-download" type="button" hidden>Download tested web app</button><p>Downloads use the Agent Concierge gateway and its public execution limits. The same saved revision can be downloaded again without another credit.</p></div></div></section>'''

SCRIPT = r'''
let hubCatalog=[],hubDrafts=[],hubProduct=null,hubDraft=null,hubReview=null,hubTesting=false,hubSuccess=false,hubDirty=false,hubTimer=null,hubInitial=null;
const hubBase=base+'/templates';
function templateText(value){/* Provenance shows as a label; the description reads as plain language. */const text=String(value||'').replace(/^Operator-provided workflow:\s*/,'');return text.charAt(0).toUpperCase()+text.slice(1);}
function syncHub(){for(const input of document.querySelectorAll('#hub-editor input'))input.disabled=busy||!loaded||(!canEdit&&input.id!=='hub-run-consent');for(const b of document.querySelectorAll('#hub-cards button,#hub-starters button'))b.disabled=busy||!loaded||!canEdit||b.dataset.needsConnection==='true'||b.dataset.unavailable==='true';$('hub-refresh').disabled=busy||!loaded;$('hub-load').disabled=busy||!loaded||!$('hub-saved').value;$('hub-review').disabled=busy||!loaded||!canEdit||uncertain||!hubProduct;$('hub-save').disabled=busy||!canEdit||uncertain||!hubReview||!$('hub-save-consent').checked||!creditReady||creditBalance<(hubReview.credit_charge??1);$('hub-run').disabled=busy||!canRun||!hubDraft||hubDirty||hubTesting||uncertain||!$('hub-run-consent').checked;$('hub-history').disabled=busy||!hubDraft;$('hub-download').disabled=busy||!canManage||!hubSuccess||hubDirty||uncertain}
function hubMessage(text){$('hub-state').textContent=text}
function hubInputs(){const values={};for(const input of $('hub-inputs').querySelectorAll('input')){if(!input.reportValidity())throw Error();values[input.name]=input.type==='number'?Number(input.value):input.value.trim()}return values}
function hubChange(){hubReview=null;hubDirty=true;hubSuccess=false;$('hub-review-box').hidden=true;$('hub-run-consent').checked=false;$('hub-download').hidden=true;syncHub()}
function hubDiscard(action){if(!hubDirty){action();return}const d=$('discard-dialog');d.onclose=()=>{if(d.returnValue==='discard')action()};d.returnValue='cancel';d.showModal()}
function hubOpen(product,draft=null){clearTimeout(hubTimer);hubProduct=product;hubDraft=draft;hubReview=null;hubDirty=false;hubSuccess=false;hubTesting=false;$('hub-editor').hidden=false;$('hub-review-box').hidden=true;$('hub-test').hidden=!draft;$('hub-results').replaceChildren();$('hub-download').hidden=true;$('hub-save-consent').checked=$('hub-run-consent').checked=false;$('hub-title').textContent=product.name;$('hub-description').textContent=templateText(product.description);$('hub-name').value=draft?.name||product.name;const protectedTemplate=Boolean(product.product);$('hub-support').textContent=protectedTemplate?'Verified fallback supported · Requires consent for each run':'Published template · Reviewed default inputs';$('hub-fallback-note').hidden=!protectedTemplate;$('hub-input-note').textContent=protectedTemplate?'Use public English search keywords only. Do not include personal or confidential information. The reviewed agent graph stays fixed.':'This version uses the published agents and default inputs shown below. Give your saved workflow a name; the published configuration stays fixed.';$('hub-run-notice').textContent=protectedTemplate?'Send these public inputs to the listed agents and allow one verified alternative source if needed.':'Send the published default inputs to the listed agents for this run.';$('hub-agents').replaceChildren();for(const step of product.nodes.filter(n=>n.type==='agent')){const p=node('section');p.append(node('h4',step.name));if(protectedTemplate)p.append(node('p','Participates in this template’s reviewed fallback route'));else{const inputs=node('dl');for(const [key,value]of Object.entries(step.data?.input||{})){inputs.append(node('dt',key.replaceAll('_',' ')),node('dd',typeof value==='object'?JSON.stringify(value):String(value)))}p.append(inputs)}$('hub-agents').append(p)}$('hub-inputs').replaceChildren();for(const fieldSpec of product.product?.inputs||[]){const label=node('label',fieldSpec.name.replaceAll('_',' ')),input=node('input');input.name=fieldSpec.name;input.id='hub-field-'+fieldSpec.name;label.htmlFor=input.id;input.type=fieldSpec.type==='integer'?'number':'text';input.required=true;if(input.type==='number'){input.min=fieldSpec.minimum;input.max=fieldSpec.maximum;input.step='1'}else{input.minLength=fieldSpec.min_length;input.maxLength=fieldSpec.max_length}const original=product.nodes.find(n=>n.id===fieldSpec.node_id)?.data?.input?.[fieldSpec.argument];input.value=draft?.inputs?.[fieldSpec.name]??original??(input.type==='number'?fieldSpec.minimum:'');input.oninput=hubChange;$('hub-inputs').append(label,input)}$('hub-editor').scrollIntoView({block:'start'});syncHub()}
let hubPage=0;
const hubPageSize=matchMedia('(max-width:700px)').matches?4:8;
const hubCategoryNames={travel_maps_weather:'Travel & Weather',dev_tools:'Developer Tools',data_utility:'Data & Utility',finance_crypto:'Finance & DeFi',automation:'Automation',sports_health:'Sports & Health',business_productivity:'Productivity',docs_knowledge:'Docs & Knowledge'};
function renderHubCatalog(){
 const query=$('hub-search').value.trim().toLowerCase(),category=$('hub-category').value;
 const matches=hubCatalog.filter(p=>(!category||p.category===category)&&(!query||[p.name,p.description,...p.nodes.map(n=>n.name)].join(' ').toLowerCase().includes(query)));
 const pages=Math.ceil(matches.length/hubPageSize);hubPage=Math.max(0,Math.min(hubPage,pages-1));$('hub-cards').replaceChildren();
 for(const product of matches.slice(hubPage*hubPageSize,(hubPage+1)*hubPageSize)){
  const card=node('article');card.className='hub-card';card.dataset.templateId=String(product.id);
  card.append(node('h3',product.name),node('p',templateText(product.description)));
  const badge=node('p',(String(product.description||'').startsWith('Operator-provided workflow:')?'Provided by Agent Concierge · ':'')+(product.product?'Verified fallback supported':'Published template'));badge.className='hub-badge';
  const pearls=node('div');pearls.className='hub-agent-necklace';const steps=product.nodes.filter(n=>n.type==='agent');pearls.setAttribute('role','img');pearls.setAttribute('aria-label',steps.length+' agent steps');for(const step of steps.slice(0,6)){const pearl=node('span');pearl.className='hub-agent-pearl';pearl.title=step.name;pearls.append(pearl)}
  card.append(badge,pearls,node('p',product.nodes.filter(n=>n.type==='agent').length+' agent step'+(product.nodes.filter(n=>n.type==='agent').length===1?'':'s')+' · '+(product.product?'Editable public research inputs':'Reviewed default inputs')));
  const available=product.execution_availability?.available!==false;
  if(!available)card.append(node('p',product.execution_availability.message||'Currently unavailable. Choose another template.'));
  const choose=node('button',available?(product.product?'Use or customize template':'Use template'):'Currently unavailable');choose.type='button';choose.dataset.unavailable=String(!available);choose.onclick=()=>hubDiscard(()=>hubOpen(product));card.append(choose);$('hub-cards').append(card);
 }
 $('hub-page').textContent=matches.length?'Showing '+(hubPage*hubPageSize+1)+'–'+Math.min((hubPage+1)*hubPageSize,matches.length)+' of '+matches.length+' templates · Page '+(hubPage+1)+' of '+pages:'No matching templates. Try another search or category.';
 $('hub-prev').disabled=hubPage===0;$('hub-next').disabled=hubPage>=pages-1;
 hubMessage(matches.length+' of '+hubCatalog.length+' templates');syncHub();
}
async function loadHub(){
 const ready=hubInitial;hubInitial=null;const [catalog,drafts]=await Promise.all([ready?Promise.resolve({hub:ready}):api(hubBase),api(hubBase+'/drafts')]);hubCatalog=catalog.hub.templates;hubDrafts=drafts.drafts;
 const category=$('hub-category').value;$('hub-category').replaceChildren(new Option('All categories',''),...[...new Set(hubCatalog.map(p=>p.category).filter(Boolean))].map(c=>new Option(hubCategoryNames[c]||c.replaceAll('_',' '),c)));$('hub-category').value=category;
 renderHubCatalog();$('hub-saved').replaceChildren(new Option('Choose a saved template workflow',''),...hubDrafts.map(d=>new Option(d.name+' · Revision '+d.revision,d.id)));if(hubDraft)$('hub-saved').value=hubDraft.id;
 if(!hubCatalog.length)hubMessage('No published templates are available. Refresh later or use an editable starter.');syncHub();
}
$('hub-search').oninput=$('hub-category').onchange=()=>{hubPage=0;renderHubCatalog()};
for(const [id,delta]of [['hub-prev',-1],['hub-next',1]])$(id).onclick=()=>{hubPage+=delta;renderHubCatalog();$('hub-page').focus();$('hub-search').scrollIntoView({block:'start'})};
function renderHubStarters(factory){$('hub-starters').replaceChildren();for(const t of factory.templates||[]){const card=node('article');card.className='hub-card';card.append(node('h3',t.name||t.title||t.id.replaceAll('_',' ')),node('p','Editable steps · Fallback requires separate verification'));const ready=t.contracts.every(contract=>candidates.some(c=>c.contract_id===contract&&c.executable));const b=node('button',ready?'Open starter in editor':'Verified connection needed');b.type='button';b.dataset.needsConnection=String(!ready);b.onclick=()=>discardThen(()=>{const chosen=t.contracts.map(contract=>candidates.find(c=>c.contract_id===contract&&c.executable));if(chosen.some(c=>!c)){hubMessage('This starter needs another currently verified connection. Choose a protected template or another starter.');return}invalidate();flow=null;$('name').value=t.name||t.title||'My workflow';$('objective').value='';$('steps').replaceChildren();chosen.forEach((c,i)=>addStep({id:'step_'+(i+1),resource_id:c.resource_id,contract_id:c.contract_id,input:{query:'Public research',language:'en',limit:1,...(c.contract_id==='news.search.v1'?{from_utc:new Date(Date.now()-86400000).toISOString().replace(/\.\d{3}Z$/,'Z')}:{})},bindings:{},after:[],when:null}));showStage('design',true);sync();$('name').focus()});card.append(b);$('hub-starters').append(card)}}
$('hub-create-ai').onclick=()=>{showStage('design',true);$('objective').focus()};$('hub-name').oninput=hubChange;$('hub-save-consent').onchange=$('hub-run-consent').onchange=syncHub;$('hub-saved').onchange=syncHub;
$('hub-refresh').onclick=()=>work(loadHub);$('hub-load').onclick=()=>hubDiscard(()=>{const d=hubDrafts.find(d=>d.id===$('hub-saved').value),p=hubCatalog.find(p=>p.id===d?.template_id&&p.definition_hash===d?.definition_hash);if(!p){hubMessage('This saved template is no longer currently verified. Refresh templates and select a current version.');return}hubOpen(p,d)});
$('hub-review').onclick=()=>work(async()=>{const inputs=hubInputs();if(!$('hub-name').reportValidity()||!$('hub-name').value.trim())throw Error();hubReview=(await api(hubBase+'/prepare',{template_id:hubProduct.id,definition_hash:hubProduct.definition_hash,name:$('hub-name').value.trim(),inputs,draft_id:hubDraft?.id||null,revision:hubDraft?.revision||0})).review;$('hub-review-fields').replaceChildren();for(const [key,value] of Object.entries({Name:hubReview.proposal.name,...inputs}))$('hub-review-fields').append(node('dt',key),node('dd',String(value)));$('hub-charge').textContent='Saving this version uses '+hubReview.credit_charge+' credit'+(hubReview.credit_charge===1?'':'s')+'.';$('hub-save-consent').checked=false;$('hub-review-box').hidden=false;syncHub()},false,'template');
$('hub-save').onclick=()=>{const chosen=hubReview;if(!chosen||!$('hub-save-consent').checked)return;creditThen(chosen.credit_charge,()=>work(async()=>{if(chosen!==hubReview||!$('hub-save-consent').checked)throw Error();const result=await api(hubBase+'/drafts',{proposal:chosen.proposal,signature:chosen.signature,authorized:true,notice:chosen.notice});hubOpen(hubProduct,result.draft);await Promise.all([loadHub(),creditStatus()]);hubMessage('Template saved. Review and approve sharing before running it.')}))};
async function hubHistory(){clearTimeout(hubTimer);if(!hubDraft)return;const v=await api(hubBase+'/drafts/'+hubDraft.id+'/runs');$('hub-results').replaceChildren();hubSuccess=false;hubTesting=false;for(const run of v.runs){const section=node('section');section.append(node('h4',new Date(run.created*1000).toLocaleString('en-US')+' · '+run.status));const summary=run.result_summary;if(typeof summary==='string')section.append(node('p',summary));for(const item of run.node_results||[]){section.append(node('p',(item.name||'Agent step')+' · '+item.status));const raw=item.data||item.output;const result=raw?.structuredContent||raw;for(const entry of result?.items||[])section.append(node('p',entry.title||entry.name||'Research record'))}if(run.revision===hubDraft.revision&&run.status==='succeeded')hubSuccess=true;if(run.revision===hubDraft.revision&&['queued','running'].includes(run.status))hubTesting=true;$('hub-results').append(section)}$('hub-download').hidden=!hubSuccess;syncHub();if(hubTesting&&!document.hidden)hubTimer=setTimeout(()=>{if(!busy)work(hubHistory);else hubTimer=setTimeout(()=>work(hubHistory),3000)},2000)}
$('hub-run').onclick=()=>work(async()=>{if(!$('hub-run-consent').checked||hubDirty)throw Error();$('hub-run-consent').checked=false;hubTesting=true;hubMessage('Starting your saved template…');await api(hubBase+'/drafts/'+hubDraft.id+'/runs',{revision:hubDraft.revision,request_id:crypto.randomUUID().replaceAll('-',''),authorized:true,notice:hubProduct.product?'run-reviewed-template-with-alternative-v1':'run-reviewed-template-defaults-v1'});await hubHistory();hubMessage('Run accepted. Check progress below; requests are not repeated automatically.')});
$('hub-history').onclick=()=>work(hubHistory);document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(hubTimer)});
$('hub-download').onclick=()=>work(async()=>{const response=await fetch(hubBase+'/drafts/'+hubDraft.id+'/versions/'+hubDraft.revision+'/package',{credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(30000)});if(!response.ok)throw Error();const url=URL.createObjectURL(await response.blob()),a=node('a');a.href=url;a.download='my-workflow.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);await creditStatus();hubMessage('Your tested web app was downloaded. Saving later edits uses a new credit.')});
'''


def inject(html):
    html = html.replace('<section id="library"', MARKUP+'<section id="library"', 1)
    html = html.replace('<a href="#library">Browse your saved workflows</a>', '<button id="hub-create-ai" type="button">Create with AI</button><a href="#template-hub">Template Hub</a><a href="#library">Your saved workflows</a>')
    html = html.replace('</style>', '.hub-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:16px}.hub-card{padding:20px;border:1px solid var(--line);border-radius:16px}.hub-badge{display:inline-block;padding:6px 12px;border-radius:999px;background:light-dark(#e5f4ed,#17382c);color:light-dark(#155a3c,#a7ebc7);font-size:.88rem}.hub-filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:12px}.hub-filters input,.hub-filters select{width:100%}.hub-pages{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:16px 0}.hub-pages span{flex:1;text-align:center}.hub-pages button{min-height:44px}#hub-agents p,#hub-agents dd{overflow-wrap:anywhere}#hub-agents dd{margin:0 0 12px}#hub-agents dt{text-transform:capitalize;font-weight:600}#template-hub{scroll-margin-top:24px}#hub-review-fields dd{overflow-wrap:anywhere;margin-bottom:12px}</style>', 1)
    html = html.replace("connectionHint.textContent=picked?.connection_reason||'';", "connectionHint.textContent=(picked?.connection_reason||'')+(picked?.fallback_template_ids?.length?' Verified fallback is available for this agent in Template Hub. This custom graph needs separate fallback verification.':'');")
    html = html.replace('syncA2a()}', 'syncA2a();syncHub()}', 1)
    html = html.replace('function setOptions(v){candidates=v.options.candidates;', 'function setOptions(v){candidates=v.options.candidates;hubInitial=v.hub||null;renderHubStarters(v.factory);', 1)
    html = html.replace('setOptions(v);loaded=true;', 'setOptions(v);loaded=true;try{await loadHub()}catch{hubMessage("Templates could not be loaded. Refresh templates to try again.")};', 1)
    html = html.replace('sync();\nfunction setOptions', SCRIPT+'\nsync();\nfunction setOptions', 1)
    return html
